import {
  AVOIDED_PAGE_MODES,
  getTableOfContentsTitle,
  safeCleanHeadingId,
  slugify,
} from '@mintlify/common';
import type { Heading, Root } from 'mdast';
import remarkSmartypants from 'remark-smartypants';
import { unified } from 'unified';

import { hasCustomHeadingId, linkedAnchor } from '../../mdx.js';
import type { FileRule } from '../../types.js';

const normalize = (value: string) => value.trim().replace(/\s+/g, ' ');

const smartypants = unified().use(remarkSmartypants);

const firstHeading = (tree: Root) =>
  tree.children.find((node): node is Heading => node.type === 'heading');

const renderedText = (heading: Heading) => {
  const clone = structuredClone(heading);
  const root: Root = { type: 'root', children: [clone] };
  smartypants.runSync(root);
  return getTableOfContentsTitle(clone);
};

export const duplicateH1: FileRule = {
  id: 'duplicate-h1',
  group: 'content',
  severity: 'warning',
  scope: 'file',
  description: 'remove a first heading that repeats the frontmatter title',
  pagesOnly: true,
  needsAnchorLinks: true,
  check: ({ tree, frontmatter, content, file, anchorLinks }) => {
    const { title, mode } = frontmatter;
    if (typeof title !== 'string' || AVOIDED_PAGE_MODES.includes(String(mode))) return [];
    const first = firstHeading(tree);
    if (!first || first.depth !== 1) return [];
    if (normalize(getTableOfContentsTitle(first)) !== normalize(title)) return [];
    const start = first.position?.start.offset ?? 0;
    const end = first.position?.end.offset ?? start;
    const location = {
      line: first.position?.start.line,
      column: first.position?.start.column,
    };
    const lineEnd = content.indexOf('\n', start);
    if (hasCustomHeadingId(content.slice(start, lineEnd === -1 ? undefined : lineEnd))) {
      return [
        {
          ...location,
          message:
            'first heading duplicates the frontmatter title; it has a custom {#id}, so remove it by hand and update links to it',
        },
      ];
    }
    const anchor = [renderedText(first), getTableOfContentsTitle(first)]
      .map((text) => linkedAnchor(anchorLinks, file, safeCleanHeadingId(slugify(text))))
      .find((linked) => linked !== undefined);
    if (anchor !== undefined) {
      return [
        {
          ...location,
          message: `first heading duplicates the frontmatter title; links point to #${anchor}, so remove it by hand and update them`,
        },
      ];
    }
    const trailing = /^\n*/.exec(content.slice(end))?.[0].length ?? 0;
    return [
      {
        ...location,
        message: 'first heading duplicates the frontmatter title',
        edit: { start, end: end + trailing, text: '' },
      },
    ];
  },
};
